# System.Runtime.Intrinsics.X86.Avx2 — lane movement, all within each 128-bit lane with one
# control for both: PALIGNR (the byte concatenation of each lane pair shifted right, 16..31
# shift zeros in, 32 and above give zero), PSHUFB (a lane whose index has bit 7 set is zero,
# otherwise `index & 15` of its own half), the immediate shuffles, the interleaving unpacks
# and the saturating packs (the first operand's lane, then the second's, per half).
# Permute4x64 and PermuteVar8x32 cross the halves: two control bits or the low three index
# bits per lane. Every immediate here is FullRangeIMM in .NET; ExtractVector128 and
# InsertVector128 read bit 0, which the compiler's intrinsic alone accepts.
target = avx2
AlignRight(v256{T},v256{T},u8) @imm8 = _mm256_alignr_epi8($0, $1, $2) for T in i8,u8,i16,u16,i32,u32,i64,u64
ExtractVector128(v256{T},u8) @imm8 @ref(($1 & 1) != 0 ? $0.GetUpper() : $0.GetLower()) = _mm256_extracti128_si256($0, $1 & 1) for T in i8,u8,i16,u16,i32,u32,i64,u64
InsertVector128(v256{T},v128{T},u8) @imm8 @ref(($2 & 1) != 0 ? $0.WithUpper($1) : $0.WithLower($1)) = _mm256_inserti128_si256($0, $1, $2 & 1) for T in i8,u8,i16,u16,i32,u32,i64,u64
MoveMask(v256{T}) @ref((int)Vector256.ExtractMostSignificantBits($0)) = _mm256_movemask_epi8($0) for T in i8,u8
MultipleSumAbsoluteDifferences(v256u8,v256u8,u8) @imm8 = _mm256_mpsadbw_epu8($0, $1, $2)
PackSignedSaturate(v256i16,v256i16) = _mm256_packs_epi16($0, $1)
PackSignedSaturate(v256i32,v256i32) = _mm256_packs_epi32($0, $1)
PackUnsignedSaturate(v256i16,v256i16) = _mm256_packus_epi16($0, $1)
PackUnsignedSaturate(v256i32,v256i32) = _mm256_packus_epi32($0, $1)
Permute2x128(v256{T},v256{T},u8) @imm8 @ref(Vector256.Create(($2 & 8) != 0 ? Vector128<{cs}>.Zero : ($2 & 2) != 0 ? (($2 & 1) != 0 ? $1.GetUpper() : $1.GetLower()) : (($2 & 1) != 0 ? $0.GetUpper() : $0.GetLower()), ($2 & 128) != 0 ? Vector128<{cs}>.Zero : ($2 & 32) != 0 ? (($2 & 16) != 0 ? $1.GetUpper() : $1.GetLower()) : (($2 & 16) != 0 ? $0.GetUpper() : $0.GetLower()))) = _mm256_permute2x128_si256($0, $1, $2) for T in i8,u8,i16,u16,i32,u32,i64,u64
Permute4x64(v256{T},u8) @imm8 @ref(Vector256.Shuffle($0, Vector256.Create(({cs})($1 & 3), ({cs})(($1 >> 2) & 3), ({cs})(($1 >> 4) & 3), ({cs})(($1 >> 6) & 3)))) = _mm256_permute4x64_epi64($0, $1) for T in i64,u64
