PermuteVar8x32(v256{T},v256{T}) @ref(Vector256.Shuffle($0, $1 & Vector256.Create(({cs})7))) = _mm256_permutevar8x32_epi32($0, $1) for T in i32,u32
PermuteVar8x32(v256f32,v256i32) @ref(Vector256.Shuffle($0, $1 & Vector256.Create(7))) = _mm256_permutevar8x32_ps($0, $1)
Shuffle(v256i8,v256i8) @ref(Vector256.Shuffle($0, ($1 & Vector256.Create((sbyte)-113)) + Vector256.Create((sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)0, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16, (sbyte)16))) = _mm256_shuffle_epi8($0, $1)
