Shuffle(v256{T},u8) @imm8 @ref(Vector256.Shuffle($0, Vector256.Create(({cs})($1 & 3), ({cs})(($1 >> 2) & 3), ({cs})(($1 >> 4) & 3), ({cs})(($1 >> 6) & 3), ({cs})(4 + ($1 & 3)), ({cs})(4 + (($1 >> 2) & 3)), ({cs})(4 + (($1 >> 4) & 3)), ({cs})(4 + (($1 >> 6) & 3))))) = _mm256_shuffle_epi32($0, $1) for T in i32,u32
