ShuffleLow(v256{T},u8) @imm8 @ref(Vector256.Shuffle($0, Vector256.Create(({cs})($1 & 3), ({cs})(($1 >> 2) & 3), ({cs})(($1 >> 4) & 3), ({cs})(($1 >> 6) & 3), ({cs})4, ({cs})5, ({cs})6, ({cs})7, ({cs})(8 + ($1 & 3)), ({cs})(8 + (($1 >> 2) & 3)), ({cs})(8 + (($1 >> 4) & 3)), ({cs})(8 + (($1 >> 6) & 3)), ({cs})12, ({cs})13, ({cs})14, ({cs})15))) = _mm256_shufflelo_epi16($0, $1) for T in i16,u16
UnpackHigh(v256{T},v256{T}) @ref(Vector256.Create($0.GetElement(8), $1.GetElement(8), $0.GetElement(9), $1.GetElement(9), $0.GetElement(10), $1.GetElement(10), $0.GetElement(11), $1.GetElement(11), $0.GetElement(12), $1.GetElement(12), $0.GetElement(13), $1.GetElement(13), $0.GetElement(14), $1.GetElement(14), $0.GetElement(15), $1.GetElement(15), $0.GetElement(24), $1.GetElement(24), $0.GetElement(25), $1.GetElement(25), $0.GetElement(26), $1.GetElement(26), $0.GetElement(27), $1.GetElement(27), $0.GetElement(28), $1.GetElement(28), $0.GetElement(29), $1.GetElement(29), $0.GetElement(30), $1.GetElement(30), $0.GetElement(31), $1.GetElement(31))) = _mm256_unpackhi_{epi}($0, $1) for T in i8,u8
UnpackHigh(v256{T},v256{T}) @ref(Vector256.Create($0.GetElement(4), $1.GetElement(4), $0.GetElement(5), $1.GetElement(5), $0.GetElement(6), $1.GetElement(6), $0.GetElement(7), $1.GetElement(7), $0.GetElement(12), $1.GetElement(12), $0.GetElement(13), $1.GetElement(13), $0.GetElement(14), $1.GetElement(14), $0.GetElement(15), $1.GetElement(15))) = _mm256_unpackhi_{epi}($0, $1) for T in i16,u16
UnpackHigh(v256{T},v256{T}) @ref(Vector256.Create($0.GetElement(2), $1.GetElement(2), $0.GetElement(3), $1.GetElement(3), $0.GetElement(6), $1.GetElement(6), $0.GetElement(7), $1.GetElement(7))) = _mm256_unpackhi_{epi}($0, $1) for T in i32,u32
